import { Controller, Get, Param, ParseUUIDPipe, UseGuards } from '@nestjs/common';
import {
  CurrentUser,
  JwtAuthGuard,
  type AuthenticatedUser,
} from '../auth/jwt-auth.guard';
import { InvoiceLinesService, type InvoiceLineView } from './invoice-lines.service';

@Controller('api/invoices')
@UseGuards(JwtAuthGuard)
export class InvoiceLinesController {
  constructor(private readonly lines: InvoiceLinesService) {}

  @Get(':invoiceId/lines')
  async list(
    @Param('invoiceId', ParseUUIDPipe) invoiceId: string,
    @CurrentUser() actor: AuthenticatedUser,
  ): Promise<InvoiceLineView[]> {
    return this.lines.listForInvoice(invoiceId, actor);
  }

  @Get(':invoiceId/tax-total')
  async taxTotal(
    @Param('invoiceId', ParseUUIDPipe) invoiceId: string,
    @CurrentUser() actor: AuthenticatedUser,
  ): Promise<{ taxCents: number }> {
    return { taxCents: await this.lines.taxTotalCents(invoiceId, actor) };
  }
}

