import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Invoice } from '../billing/entities/invoice.entity';
import { LedgerAdjustment } from '../billing/entities/ledger-adjustment.entity';

export interface AdjustmentView {
  id: string;
  invoiceReference: string;
  amountCents: number;
  memo: string;
  createdAt: string;
}

export interface RecordAdjustmentInput {
  organisationId: string;
  invoiceId: string;
  amountCents: number;
  memo: string;
  createdById: string;
}

@Injectable()
export class AdjustmentsService {
  private readonly logger = new Logger(AdjustmentsService.name);

  constructor(
    @InjectRepository(LedgerAdjustment)
    private readonly adjustments: Repository<LedgerAdjustment>,
    @InjectRepository(Invoice)
    private readonly invoices: Repository<Invoice>,
  ) {}

  async listForOrganisation(organisationId: string, take: number): Promise<AdjustmentView[]> {
    const rows = await this.adjustments
      .createQueryBuilder('adjustment')
      .innerJoin(Invoice, 'invoice', 'invoice.id = adjustment.invoiceId')
      .select([
        'adjustment.id AS id',
        'adjustment.amountCents AS amount',
        'adjustment.memo AS memo',
        'adjustment.createdAt AS created_at',
        'invoice.reference AS reference',
      ])
      .where('adjustment.organisationId = :organisationId', { organisationId })
      .orderBy('adjustment.createdAt', 'DESC')
      .take(take)
      .getRawMany<{
        id: string;
        amount: string;
        memo: string;
        created_at: Date;
        reference: string;
      }>();

    return rows.map((row) => ({
      id: row.id,
      invoiceReference: row.reference,
      amountCents: Number(row.amount),
      memo: row.memo,
      createdAt: row.created_at.toISOString(),
    }));
  }

  /** Book the correction and move the invoice balance with it. */
  async record(input: RecordAdjustmentInput): Promise<AdjustmentView> {
    const invoice = await this.invoices.findOne({
      where: { id: input.invoiceId, organisationId: input.organisationId },
    });

    if (!invoice) {
      throw new NotFoundException(`Invoice ${input.invoiceId} does not exist`);
    }

    const adjustment = await this.adjustments.save(
      this.adjustments.create({
        organisationId: invoice.organisationId,
        invoiceId: invoice.id,
        amountCents: input.amountCents,
        memo: input.memo,
        createdById: input.createdById,
      }),
    );

    await this.invoices.increment({ id: invoice.id }, 'balanceCents', input.amountCents);

    this.logger.warn(
      `ledger adjustment ${adjustment.id} of ${input.amountCents} cents on ${invoice.reference}`,
    );

    return {
      id: adjustment.id,
      invoiceReference: invoice.reference,
      amountCents: adjustment.amountCents,
      memo: adjustment.memo,
      createdAt: adjustment.createdAt.toISOString(),
    };
  }
}

