import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { AccountStatement } from '../billing/entities/account-statement.entity';

@Injectable()
export class StatementIndexService {
  constructor(
    @InjectRepository(AccountStatement)
    private readonly statements: Repository<AccountStatement>,
  ) {}

  /** The indexed statement for one organisation, or null if it predates the index. */
  async findForOrganisation(
    reference: string,
    organisationId: string,
  ): Promise<AccountStatement | null> {
    return this.statements.findOne({ where: { reference, organisationId } });
  }
}

