import {
  Body,
  Controller,
  Get,
  HttpCode,
  Param,
  ParseUUIDPipe,
  Post,
  UseGuards,
} from '@nestjs/common';
import {
  CurrentUser,
  JwtAuthGuard,
  type AuthenticatedUser,
} from '../auth/jwt-auth.guard';
import { CreditNotesService, type CreditNoteView } from './credit-notes.service';
import { IssueCreditNoteDto } from './dto/issue-credit-note.dto';

@Controller('api/credit-notes')
@UseGuards(JwtAuthGuard)
export class CreditNotesController {
  constructor(private readonly creditNotes: CreditNotesService) {}

  @Get('for-invoice/:invoiceId')
  async listForInvoice(
    @Param('invoiceId', ParseUUIDPipe) invoiceId: string,
    @CurrentUser() actor: AuthenticatedUser,
  ): Promise<CreditNoteView[]> {
    return this.creditNotes.listForInvoice(invoiceId, actor);
  }

  @Post()
  @HttpCode(201)
  async issue(
    @Body() body: IssueCreditNoteDto,
    @CurrentUser() actor: AuthenticatedUser,
  ): Promise<CreditNoteView> {
    return this.creditNotes.issue(body, actor);
  }
}

