import type { FastifyPluginAsync } from 'fastify';

import { applyPayoutSettingsPatch, getPayoutSettings } from '../domain/payout-settings.js';
import { getSession, requireSession } from '../lib/session.js';

/**
 * Settings editor in the merchant dashboard. The editor sends whichever fields
 * the merchant touched, so the body is a partial settings document.
 */
const merchantSettingsRoutes: FastifyPluginAsync = async (fastify) => {
  fastify.addHook('preHandler', requireSession);

  fastify.get('/api/merchant/payout-settings', async (request, reply) => {
    const session = getSession(request);
    const settings = await getPayoutSettings(session.merchantId);
    if (!settings) {
      return reply.code(404).send({ error: 'payout_settings_not_found' });
    }
    return { settings };
  });

  fastify.patch<{ Body: Record<string, unknown> }>(
    '/api/merchant/payout-settings',
    {
      schema: {
        body: { type: 'object', additionalProperties: true, minProperties: 1 },
      },
    },
    async (request) => {
      const session = getSession(request);
      const settings = await applyPayoutSettingsPatch(session.merchantId, request.body);
      request.log.info({ merchantId: session.merchantId }, 'payout settings updated');
      return { settings };
    },
  );
};

export default merchantSettingsRoutes;

