import type { FastifyPluginAsync } from 'fastify';

import { applyPreferencePatch, getPreferences } from '../domain/merchant-preferences.js';
import { getSession, requireSession } from '../lib/session.js';

/**
 * Notification preferences pane. Like the payout settings editor it sends a
 * partial document, so the body is an open object here and the domain module
 * decides which keys the merchant is allowed to move.
 */
const merchantPreferenceRoutes: FastifyPluginAsync = async (fastify) => {
  fastify.addHook('preHandler', requireSession);

  fastify.get('/api/merchant/preferences', async (request, reply) => {
    const session = getSession(request);
    const preferences = await getPreferences(session.merchantId);
    if (!preferences) {
      return reply.code(404).send({ error: 'preferences_not_found' });
    }
    return { preferences };
  });

  fastify.patch<{ Body: Record<string, unknown> }>(
    '/api/merchant/preferences',
    {
      schema: {
        body: { type: 'object', additionalProperties: true, minProperties: 1 },
      },
    },
    async (request) => {
      const session = getSession(request);
      const preferences = await applyPreferencePatch(session.merchantId, request.body);
      return { preferences };
    },
  );
};

export default merchantPreferenceRoutes;

